insert into public.lessons (id, textbook_id, title, position) values ('00000000-0000-4000-8001-000000000301', '00000000-0000-4000-8000-000000000001', '3A – Where were you last weekend?', 30);
insert into public.cards (lesson_id, en, cz, note) select '00000000-0000-4000-8001-000000000301', r->>0, r->>1, r->>2 from jsonb_array_elements('[["on holiday", "na dovolené, na prázdninách", ""], ["at a wedding", "na svatbě", ""], ["in the garden", "na zahradě", ""], ["at work", "v práci", ""], ["on the beach", "na pláži", "Pozor na předložku: on the beach."], ["in bed", "v posteli", "Bez „the“: in bed."], ["at a theme park", "v zábavním parku", ""], ["at home", "doma", "Bez „the“: at home."]]'::jsonb) r;
insert into public.lessons (id, textbook_id, title, position) values ('00000000-0000-4000-8001-000000000302', '00000000-0000-4000-8000-000000000001', '3B – Our holiday', 31);
insert into public.cards (lesson_id, en, cz, note) select '00000000-0000-4000-8001-000000000302', r->>0, r->>1, r->>2 from jsonb_array_elements('[["a plane", "letadlo", ""], ["a runway", "přistávací a vzletová dráha", ""], ["an airport", "letiště", ""], ["passengers", "cestující", ""], ["a taxi", "taxi, taxík", ""], ["a ticket", "jízdenka, letenka", ""], ["a passport", "cestovní pas", ""], ["a label", "jmenovka (na zavazadle), štítek", ""], ["a trolley", "vozík (na zavazadla)", ""], ["luggage", "zavazadla", "Nepočitatelné: some luggage, ne „a luggage“."], ["a suitcase", "kufr", ""], ["a rucksack", "batoh", "Americky „a backpack“."], ["a campsite", "kemp, tábořiště", ""], ["a caravan", "obytný přívěs, karavan", ""], ["a tent", "stan", ""]]'::jsonb) r;
insert into public.lessons (id, textbook_id, title, position) values ('00000000-0000-4000-8001-000000000303', '00000000-0000-4000-8000-000000000001', '3C – Holiday problems', 32);
insert into public.cards (lesson_id, en, cz, note) select '00000000-0000-4000-8001-000000000303', r->>0, r->>1, r->>2 from jsonb_array_elements('[["A dog bit me.", "Pokousal mě pes.", "bite → bit"], ["We forgot our passports and missed the plane.", "Zapomněli jsme pasy a ujelo nám letadlo.", "forget → forgot"], ["They took the wrong bus and got lost.", "Nastoupili do špatného autobusu a ztratili se.", "take → took, get → got"], ["I lost my camera with all my photos in it.", "Ztratil jsem foťák se všemi fotkami.", "lose → lost"], ["I fell over and broke my arm.", "Upadl jsem a zlomil si ruku.", "fall over → fell over, break → broke"], ["She left her bag on the train.", "Nechala tašku ve vlaku.", "leave → left"], ["He felt seasick.", "Měl mořskou nemoc.", "feel → felt"], ["Someone stole my mobile.", "Někdo mi ukradl mobil.", "steal → stole"], ["leave – left", "nechat, odejít – nechal, odešel", "Nepravidelné sloveso"], ["forget – forgot", "zapomenout – zapomněl", "Nepravidelné sloveso"], ["break – broke", "zlomit, rozbít – zlomil, rozbil", "Nepravidelné sloveso"], ["steal – stole", "ukrást – ukradl", "Nepravidelné sloveso"], ["fall over – fell over", "upadnout – upadl", "Nepravidelné sloveso"], ["bite – bit", "kousnout – kousl", "Nepravidelné sloveso"], ["lose – lost", "ztratit – ztratil", "Nepravidelné sloveso"], ["feel – felt", "cítit se – cítil se", "Nepravidelné sloveso"], ["take – took", "vzít, jet (čím) – vzal, jel", "Nepravidelné sloveso"], ["get – got", "dostat, stát se – dostal, stal se", "Nepravidelné sloveso. Get lost = ztratit se."]]'::jsonb) r;
